def diagnose(question, selected):
    if selected == question["correct"]:
        return {"correct": True, "category": None, "explanation": question["correct_why"], "followup": None}
    issue = question.get("misconceptions", {}).get(str(selected), {"category":"Misreading binary truth tables", "why":"Compare the selected option with the input values and the gate's truth table."})
    return {"correct": False, "category": issue["category"], "explanation": issue["why"], "followup": question["followup"]}

def score_answers(answers, questions=None):
    by_id = {q["id"]: q for q in (questions or QUESTIONS)}
    results = []
    for item in answers:
        q = by_id.get(item["question_id"])
        if q is None:
            raise ValueError("Unknown question id")
        selected = item["answer"]
        if not isinstance(selected, int) or selected < 0 or selected >= len(q["options"]):
            raise ValueError("Answer choice is out of range")
        results.append({"question_id":q["id"], "selected":selected, "selected_text":q["options"][selected], **diagnose(q, selected)})
    return {"score":sum(r["correct"] for r in results), "total":len(results), "results":results,
            "revision_concepts":list(dict.fromkeys(r["category"] for r in results if r["category"]))}
